/// Provenance headers for generated datasource files (spec #1131, order 5).
///
/// Every file the datasource plugin freshly emits (interface, remote,
/// local) is stamped with a `// GENERATED by zfa datasource` header plus a
/// regeneration hint, mirroring the provider convention (spec #979). The
/// header lets `zfa proof check`-style provenance audits and humans
/// distinguish generated datasources from hand-written ones, and names the
/// exact command that reproduces the artifact.
///
/// Append/merge runs never re-stamp: they read the existing source and the
/// AST engine preserves the leading comment block (the header stays the
/// first thing in the file).
library;

/// The provenance header factory for the datasource plugin.
abstract final class DatasourceProvenance {
  /// The provenance marker line stamped on every freshly emitted
  /// datasource file (spec #1131 order 5).
  static const String generatedHeader =
      '// GENERATED by zfa datasource — DO NOT EDIT BY HAND.';

  /// The full header block (marker + regeneration hint) for one emitted
  /// file. [entityName] is the PascalCase entity the file was generated
  /// for; [variant] describes the file shape (`datasource interface`,
  /// `remote datasource`, `local datasource`).
  static String headerFor(String entityName, String variant) =>
      '$generatedHeader\n'
      '// Regenerate with: zfa datasource create $entityName '
      '(--force to overwrite). Variant: $variant.\n\n';
}
